181→/**
182→ * Load the registry from IPNS (read-only).
183→ *
184→ * Used by the polling hook (Plan 03) to check for remote changes.
185→ * Does NOT modify the registry -- just resolves, fetches, and decrypts.
186→ *
187→ * @returns Registry data with IPNS name and sequence number, or null on failure
188→ */
189→export async function loadRegistry(userPrivateKey: Uint8Array): Promise<{
190→  registry: DeviceRegistry;
191→  ipnsName: string;
192→  sequenceNumber: bigint;
193→} | null> {
194→  try {
195→    const registryIpns = await deriveRegistryIpnsKeypair(userPrivateKey);
196→    const resolved = await resolveIpnsRecord(registryIpns.ipnsName);
197→
198→    if (!resolved) {
199→      return null;
200→    }
201→
202→    const encryptedBytes = await fetchFromIpfs(resolved.cid);
203→    const registry = await decryptRegistry(encryptedBytes, userPrivateKey);
204→
205→    return {
206→      registry,
207→      ipnsName: registryIpns.ipnsName,
208→      sequenceNumber: resolved.sequenceNumber,
209→    };
210→  } catch (error) {
211→    console.error('[DeviceRegistry] Failed to load registry:', error);
212→    return null;
213→  }
214→}
